package com.franco.desco.adapter.out.sqlserver.crates;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.crates.*;import com.franco.desco.application.crates.port.out.CratePersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.crates.CrateModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class CrateSqlServerAdapter implements CratePersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,balance,history,receive,assign,returnCall,annul;public CrateSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("comercial","PA_Jabas_Sel_Listado","items");balance=f.callWithResultSets("comercial","PA_Jabas_Sel_Saldo","balance");history=f.callWithResultSets("comercial","PA_Jabas_Sel_Historial","items");receive=f.call("comercial","PA_Jabas_Ins_Recepcion");assign=f.call("comercial","PA_Jabas_Ins_Asignacion");returnCall=f.call("comercial","PA_Jabas_Ins_Devolucion");annul=f.call("comercial","PA_Jabas_Upd_AnularMovimiento");}
 public PersistenceResult<PageResult<CrateModels.Summary>>list(CrateCommands.ListCrates c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var out=e.executeJson(list,pf.forQuery(i,m,map("filtros",map("operativoVentaId",f==null?null:f.operativoVentaId()),"paginacion",map("pagina",pg.pagina(),"tamano",pg.tamanio()))));return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudo consultar el control de jabas.");}
 public PersistenceResult<CrateModels.Balance>balance(CrateCommands.Balance c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(balance,pf.forQuery(i,m,Map.of("jabas",map("operativoVentaId",c.operativoVentaId(),"operativoSocioId",c.operativoSocioId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar el saldo."));var r=one(out,"balance");return r==null?PersistenceResult.error("No se pudo obtener el saldo de jabas."):PersistenceResult.ok(PaAdapterSupport.message(out,"Saldo consultado correctamente."),new CrateModels.Balance(SqlValues.longValue(r,"operativoVentaId"),SqlValues.longValue(r,"operativoSocioId"),SqlValues.intValue(r,"recibidas"),SqlValues.intValue(r,"asignadas"),SqlValues.intValue(r,"devueltas"),SqlValues.intValue(r,"pendientes"),SqlValues.intValue(r,"disponibles")));}
 public PersistenceResult<List<CrateModels.History>>history(CrateCommands.History c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(history,pf.forQuery(i,m,Map.of("filtros",map("operativoVentaId",c.operativoVentaId(),"operativoSocioId",c.operativoSocioId()))));return PaAdapterSupport.result(out,rows(out,"items").stream().map(this::historyRow).toList(),"No se pudo consultar el historial de jabas.");}
 public PersistenceResult<Long>receive(CrateCommands.Receive c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(receive,pf.forWrite(i,m,c,Map.of("jabas",map("operativoVentaId",c.operativoVentaId(),"cantidad",c.cantidad(),"referencia",c.referencia(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nJabaMovimientoId"),"No se pudo registrar la recepción de jabas.");}public PersistenceResult<Long>assign(CrateCommands.Assign c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(assign,pf.forWrite(i,m,c,Map.of("jabas",map("operativoSocioId",c.operativoSocioId(),"cantidad",c.cantidad(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nJabaAsignacionId"),"No se pudo registrar la asignación de jabas.");}public PersistenceResult<Long>returnCrates(CrateCommands.ReturnCrates c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(returnCall,pf.forWrite(i,m,c,Map.of("jabas",map("jabaAsignacionId",c.jabaAsignacionId(),"entregaSocioId",c.entregaSocioId(),"cantidadLlenas",c.cantidadLlenas(),"cantidadVacias",c.cantidadVacias(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nJabaDevolucionId"),"No se pudo registrar la devolución de jabas.");}public PersistenceResult<Void>annul(CrateCommands.Annul c,SessionIdentity i,RequestMetadata m){return PaAdapterSupport.result(e.executeJson(annul,pf.forWrite(i,m,c,Map.of("jabas",map("tipo",c.tipo(),"movimientoId",c.movimientoId(),"motivo",c.motivo())))),null,"No se pudo anular el movimiento de jabas.");}
 private CrateModels.Summary summary(Map<String,Object>r){return new CrateModels.Summary(SqlValues.longValue(r,"operativoVentaId"),SqlValues.string(r,"codigo"),SqlValues.string(r,"estadoProceso"),SqlValues.intValue(r,"cantidadJabasRecibidas"),SqlValues.longValue(r,"jabasAsignadas"),SqlValues.longValue(r,"jabasDevueltasLlenas"),SqlValues.longValue(r,"jabasDevueltasVacias"),SqlValues.longValue(r,"jabasDevueltas"),SqlValues.longValue(r,"jabasDisponibles"),SqlValues.longValue(r,"jabasPendientes"));}private CrateModels.History historyRow(Map<String,Object>r){return new CrateModels.History(SqlValues.longValue(r,"jabaMovimientoId"),SqlValues.longValue(r,"operativoVentaId"),SqlValues.longValue(r,"operativoSocioId"),SqlValues.longValue(r,"jabaAsignacionId"),SqlValues.longValue(r,"jabaDevolucionId"),SqlValues.string(r,"tipoMovimiento"),SqlValues.intValue(r,"cantidad"),SqlValues.instant(r,"fechaHora"),SqlValues.string(r,"motivo"),SqlValues.string(r,"referencia"),SqlValues.bool(r,"estado"),SqlValues.string(r,"usuario"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object>one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
